def count_paths(grid):
    rows, cols = len(grid), len(grid[0])
    memo = [[None] * cols for _ in range(rows)]

    def recurse(row, col):
        if row > rows - 1 or col > cols - 1:
            return 0
        if grid[row][col] == 1:
            return 0
        if row == rows - 1 and col == cols - 1:
            return 1
        if memo[row][col] is not None:
            return memo[row][col]
        result = recurse(row + 1, col) + recurse(row, col + 1)
        memo[row][col] = result
        return result

    return recurse(0, 0)
```

