def count_paths(grid):
    m, n = len(grid), len(grid[0])
    if m == 0 or n == 0:
        return 0
    if grid[0][0] == 1 or grid[m - 1][n - 1] == 1:
        return 0
    from functools import lru_cache

    @lru_cache
    def paths(i, j):
        if i == m - 1 and j == n - 1:
            return 1
        if i < m - 1 and grid[i + 1][j] == 0:
            down = paths(i + 1, j)
        else:
            down = 0
        if j < n - 1 and grid[i][j + 1] == 0:
            right = paths(i, j + 1)
        else:
            right = 0
        return down + right

    return paths(0, 0)
```

