def intersection_car_pass_count(events, green_duration):
    north_south = 0
    east_west = 0
    for tick, direction in events:
        if direction in ('N', 'S'):
            if tick < green_duration:
                north_south += 1
        elif direction in ('E', 'W'):
            if tick >= green_duration:
                east_west += 1
    return north_south + east_west
```

