def parking_garage_fees(events, rate):
    parked = {}
    fees = {}
    for op, car_id, time in events:
        if op == 'enter':
            if car_id not in parked:
                parked[car_id] = time
        elif op == 'exit' and car_id in parked:
            stay = time - parked[car_id]
            fees[car_id] = stay * rate
            del parked[car_id]
    return fees
```

