def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    visited = set()
    if start_floor in requests:
        visited.add(start_floor)
    floor = start_floor
    while True:
        if direction == 1:
            floor += 1
            if floor > top_floor:
                break
        else:
            floor -= 1
            if floor < 1:
                break
        if floor in requests:
            visited.add(floor)
    return sorted(visited)
```

