```python
def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def light_phase(t, durations):
        r, g, y = durations
        cycle_length = r + g + y
        leftover = t % cycle_length
        if leftover < r:
            return 'RED'
        elif leftover < r + g:
            return 'GREEN'
        else:
            return 'YELLOW'
    count = 0
    for t in range(n_ticks):
        if light_phase(t, durations_a) == 'GREEN' and light_phase(t, durations_b) == 'GREEN':
            count += 1
    return count
```

