def classify_triangle_by_sides(p1, p2, p3):
    def side_length(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    ab = side_length(p1, p2)
    bc = side_length(p2, p3)
    ca = side_length(p3, p1)

    # Non-degenerate triangles must have strictly positive lengths
    if ab <= 0 or bc <= 0 or ca <= 0:
        return 'scalene'

    a, b, c = sorted((ab, bc, ca))

    if a == b == c:
        return 'equilateral'
    elif a == b or b == c:
        return 'isosceles'
    else:
        return 'scalene'

