def is_square(p1, p2, p3, p4):
    def dist2(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    sides = [dist2(p1, p2), dist2(p2, p3), dist2(p3, p4), dist2(p4, p1)]
    diags = [dist2(p1, p3), dist2(p1, p4), dist2(p2, p3), dist2(p2, p4)]

    side_counts = {d: 0 for d in sides}
    for d in sides:
        side_counts[d] += 1

    diag_counts = {d: 0 for d in diags}
    for d in diags:
        diag_counts[d] += 1

    side_values = sorted(set(sides))
    diag_values = sorted(set(diags))

    if len(side_values) != 1 or len(diag_values) != 1:
        return False

    a, b = side_values[0], diag_values[0]
    return a * 2 == b
```

