def count_paths(grid):
    rows = len(grid)
    cols = len(grid[0])
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1 if grid[0][0] == 0 else 0

    for r in range(rows):
        for c in range(1, cols):
            if grid[r][c] == 0:
                dp[r][c] = dp[r][c - 1]
            else:
                dp[r][c] = 0
    for c in range(cols):
        for r in range(1, rows):
            if grid[r][c] == 0:
                dp[r][c] += dp[r - 1][c]

    return dp[-1][-1]
```

