def compare_semver(v1, v2):
    m1, n1, p1 = map(int, v1.split('.'))
    m2, n2, p2 = map(int, v2.split('.'))
    if m1 < m2:
        return -1
    if m1 > m2:
        return 1
    if n1 < n2:
        return -1
    if n1 > n2:
        return 1
    if p1 < p2:
        return -1
    if p1 > p2:
        return 1
    return 0
```

