```python
def parse_duration(s):
    total = 0
    digits = []
    for c in s:
        if c == ' ':
            continue
        if c.isdigit():
            digits.append(c)
        else:
            if digits:
                value = int(''.join(digits))
                digits = []
                if c == 'h':
                    total += value * 60
                elif c == 'm':
                    total += value
                else:
                    raise ValueError('unrecognised marker')
            else:
                raise ValueError('digit expected after marker')
    if digits:
        raise ValueError('incomplete marker')
    return total
```

