import urllib.parse
import socket

def parse_url_parts(url):
    parts = urllib.parse.urlparse(url)
    return {
        'scheme': parts.scheme,
        'host': parts.hostname or parts.netloc,
        'path': parts.path or '',
        'query': parts.fragment or ''
    }

def _resolve_host(name):
    try:
        socket.getaddrinfo(name, None)
    except socket.gaierror:
        return 'HttpNotFound'
    return name

def _all_queries(match):
    return ''.join(match.groups()) or ''

def _join_queries(source, target):
    if not source:
        return target
    if not target:
        return source
    return source + '&' + target
```

