def parse_multiline_kv(s):
    'Parses a multi-line key-value string into a dictionary, with later lines overwriting.'
    d = {}
    buffer = []
    for c in s:
        if c == '\n':
            line = ''.join(buffer)
            if not line:
                buffer.clear()
                continue
            value = line
            prefix = []
            for x in line:
                prefix.append(x)
                if len(prefix) == 2 and prefix[0] == ':' and prefix[1] == ' ':
                    break
            else:
                buffer.clear()
                continue
            buffer = line[len(prefix):]
            prefix = ''.join(prefix)
            if prefix == ': ' and buffer:
                d[buffer] = value
            else:
                d[value] = ''
        else:
            buffer.append(c)
    if buffer:
        line = ''.join(buffer)
        value = line
        prefix = []
        for x in line:
            prefix.append(x)
            if len(prefix) == 2 and prefix[0] == ':' and prefix[1] == ' ':
                break
        else:
            return d
        buffer = line[len(prefix):]
        prefix = ''.join(prefix)
        if prefix == ': ' and buffer:
            d[buffer] = value
    return d
```

