def parse_env_line(line):
    if '=' not in line:
        return (line, '')
    key, raw_value = line.split('=', 1)
    key = key.strip()
    value = raw_value
    for start, c in enumerate(raw_value):
        if c in ('"', "'"):
            end = raw_value.find(c, start + 1)
            if end >= 0:
                value = raw_value[start + 1:end]
                break
    return (key, value)
```

