def count_paths(grid):
    if grid[0][0] or grid[-1][-1]:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = [[0] * cols for _ in range(rows)]
    for i in range(rows):
        if grid[i][0] == 1:
            break
        count[i][0] = 1
    for j in range(1, cols):
        if grid[0][j] == 1:
            break
        count[0][j] = 1
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 1:
                count[i][j] = 0
            else:
                count[i][j] = count[i - 1][j] + count[i][j - 1]
    return count[-1][-1]
```

