```python
def parking_lot_occupancy(events, capacity):
    count = 0
    occupied = dict()  # maps spot to car number
    for num, (op, sid) in enumerate(events):
        if op == 'enter':
            if sid not in occupied:
                if count < capacity:
                    occupied[sid] = num
                    count += 1
        else:
            occupied.pop(sid, None)
    return sorted(occupied)
```

