def rate_limiter_allowed(timestamps, limit, window):
    i = 0
    for t in timestamps:
        while i < len(timestamps) and timestamps[i] < t - window:
            i += 1
        if i < len(timestamps) and timestamps[i] <= t:
            return False
    return [True] * len(timestamps)
```

