```python
def shopping_cart_total(events):
    from collections import defaultdict
    cart = defaultdict(lambda: [0, 0])  # quantity, then price
    for name, *args in events:
        if name == 'add':
            item, qty, price = args
            cart[item][0] += qty
            cart[item][1] = price  # later add wins price
        elif name == 'remove':
            item, qty = args
            entry = cart[item]
            entry[0] -= qty
            if entry[0] <= 0:
                del cart[item]
        elif name == 'clear':
            cart.clear()
    return sum(qty * price for qty, price in cart.values())
```

