def coffee_machine_credit(events, prices, stock):
    credit = 0
    cups = dict(stock)
    dispensed = 0

    for op, val in events:
        if op == "insert":
            credit += val
        elif op == "select":
            if val not in prices or cups[val] <= 0:
                continue
            price = prices[val]
            if credit < price:
                continue
            credit -= price
            cups[val] -= 1
            dispensed += 1
    return (credit, dict(cups), dispensed)
```

