def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requested = sorted(set(requests))
    if not requested:
        return []
    removes = set()
    for stop in requested:
        if stop == start_floor or stop + direction in removes:
            removes.add(stop)
    if direction > 0:
        return [s for s in requested if s not in removes]
    else:
        return [s for s in reversed(requested) if s not in removes]
```

