```python
def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    requested = set(requests)
    stops = []
    stop = start_floor
    if direction == 1:
        while stop <= top_floor:
            if stop in requested:
                stops.append(stop)
            stop += 1
    else:
        while stop >= 1:
            if stop in requested:
                stops.append(stop)
            stop -= 1
    return stops
```

