def spiral_order(grid):
    rows, cols = len(grid), len(grid[0])
    if rows == 0 or cols == 0:
        return []

    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while top <= bottom and left <= right:
        for y in range(left, right + 1):
            result.append(grid[top][y])
        top += 1
        for x in range(top, bottom + 1):
            result.append(grid[x][right])
        right -= 1
        if top <= bottom:
            for y in range(right, left - 1, -1):
                result.append(grid[bottom][y])
            bottom -= 1
        if left <= right:
            for x in range(bottom, top - 1, -1):
                result.append(grid[x][left])
            left += 1

    return result
```

