def elevator_floor(start_floor, commands, min_floor, max_floor):
    m = int(min_floor)
    M = int(max_floor)
    current = start_floor
    for command in commands:
        if command == 'UP':
            if current < M:
                current += 1
        elif command == 'DOWN':
            if current > m:
                current -= 1
    return current
```

