def shopping_cart_total(events):
    cart = {}  # name -> (quantity, price)
    for kind, *args in events:
        if kind == 'add':
            name, qty, price = args
            current = cart.get(name, (0, 0))
            cart[name] = (current[0] + qty, price)
        elif kind == 'remove':
            name, qty = args
            if name in cart:
                quantity, price = cart[name]
                quantity -= qty
                if quantity <= 0:
                    del cart[name]
                else:
                    cart[name] = (quantity, price)
        elif kind == 'clear':
            cart.clear()
