def coffee_machine_credit(events, prices, stock):
    credit = 0
    copies = dict(stock)
    dispensed = 0
    for op, amount in events:
        if op == "insert":
            credit += amount
        elif op == "select":
            if amount in copies and copies[amount] > 0 and credit >= prices[amount]:
                copies[amount] -= 1
                credit -= prices[amount]
                dispensed += 1
    return (credit, dict(copies), dispensed)
```

